'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const current = cookieStore.get('notifications')?.value === 'on'

  cookieStore.set('notifications', current ? 'off' : 'on', {
    path: '/',
    httpOnly: true,
    sameSite: 'lax',
  })

  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotifications } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const enabled = cookieStore.get('notifications')?.value === 'on'

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

export default function RootLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
